CREATE TABLE "Room" ("id" TEXT NOT NULL PRIMARY KEY, "code" TEXT NOT NULL, "selectedGame" TEXT, "status" TEXT NOT NULL DEFAULT 'lobby', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "lastActiveAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "Room_code_key" ON "Room"("code");
CREATE TABLE "Player" ("id" TEXT NOT NULL PRIMARY KEY, "displayName" TEXT NOT NULL, "score" INTEGER NOT NULL DEFAULT 0, "roomId" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Player_roomId_fkey" FOREIGN KEY ("roomId") REFERENCES "Room" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "Player_roomId_displayName_key" ON "Player"("roomId", "displayName");
CREATE TABLE "Match" ("id" TEXT NOT NULL PRIMARY KEY, "roomId" TEXT NOT NULL, "game" TEXT NOT NULL, "winnerNames" TEXT NOT NULL, "summary" TEXT NOT NULL, "completedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Match_roomId_fkey" FOREIGN KEY ("roomId") REFERENCES "Room" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
